------------ import ------------
local KTool = CS.Engine.Lib.KTool
local ActivityPtUtils = import('Game.UI.FightReady.UIActivityPt.ActivityPtUtils')
local ActivityPtComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityPtComponent)
local cs_coroutine = require 'XLua.cs_coroutine'
------------ import ------------

---@class UIActivityPtTaskCellNode     
                       
local UIActivityPtTaskCellNode = Class('UIActivityPtTaskCellNode')

function UIActivityPtTaskCellNode:__init()
    self._data = nil
    self._cb = nil
    self._type = 1
end

function UIActivityPtTaskCellNode:__delete()
    self._data = nil
    self._cb = nil
    self._type = 1
end

function UIActivityPtTaskCellNode:Awake()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnClick))
end

function UIActivityPtTaskCellNode:Refresh(data, type, cb)
    if not data then
        return
    end
    self._data = data
    self._cb = cb
    self._type = type

    self:FillSelf()
end

function UIActivityPtTaskCellNode:FillSelf()
    local vo = self:GetActivityPtTaskVo(self._data.id)
    if not vo then
        return
    end

    local isCanDraw = ActivityPtUtils.IsTaskCanDraw(self._data.id, self._type)
    local isDraw = ActivityPtUtils.IsTaskDraw(self._data.id, self._type)
    CfUtils.SetUISwitchImage(self.BgTexture2, isCanDraw and 2 or 1)
    CfUtils.SetUISwitchImage(self.BgTexture1, isCanDraw and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgDecorate, isCanDraw and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgREN, isDraw and 2 or 1)

    CfUtils.FillText(self.NameTxt, vo.desc)
    self.Slider.value = checkNumber(self._data.progress) / checkNumber(vo.taskContenNum)
    CfUtils.FillText(self.TitleText, localize("<size=30><color=#545454>_num1_</color></size>/_num2_", {_num1_ = self._data.progress, _num2_ = vo.taskContenNum}))

    CfUtils.SetActive(self.HasReceived, isDraw)
    CfUtils.SetActive(self.FontStyleButton, not isDraw)
    local fontStyleBtn = KTool.GetComponent(self.FontStyleButton.gameObject ,typeof(CS.Game.Native.Common.FontStyleButton) )
    if isCanDraw and not isDraw then
        fontStyleBtn:ResetFontStyle("B12" , localize("领取"))
        KTool.SetActive(fontStyleBtn , true)
    elseif (not isDraw) then
        fontStyleBtn:ResetFontStyle("B13" , localize("前往"))
        KTool.SetActive(fontStyleBtn.gameObject , (not (checkInt(vo.openType)  <= 0)))
    else 
        KTool.SetActive(fontStyleBtn.gameObject , false)
    end
    CfUtils.SetActive(self.TextUnderway, not isDraw and not isCanDraw and (checkInt(vo.openType) <= 0))

    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
    if scr then
        local t1 =  CfUtils.Split(vo.rewardId)
        local t2 =  CfUtils.Split(vo.rewardNum)

        local t = {}
        for k, v in pairs(t1) do
            table.insert(t, {
                goodsId = t1[k],
                goodsNum = t2[k]
            })
        end
        scr:FreshBaseUI(t)
    end
end
function UIActivityPtTaskCellNode:GetActivityPtTaskVo(id)
    if checkInt(self._type) == 1 then
        local vo = ActivityPtUtils.GetActivityPtDayTaskVo(id)
        return vo
    elseif checkInt(self._type) == 2 then 
        local vo = ActivityPtUtils.GetActivityPtPlanTaskVo(id)
        return vo        
    end
    
end
function UIActivityPtTaskCellNode:OnClick()
    local isCanDraw = ActivityPtUtils.IsTaskCanDraw(self._data.id, self._type)
    local isDraw = ActivityPtUtils.IsTaskDraw(self._data.id, self._type)

    if isDraw then
        GameUtils.Toast(localize("已领取"))
        return
    end
    if not isCanDraw then
        local vo = self:GetActivityPtTaskVo(self._data.id)
        if checkInt(vo.openType) > 0 then
            cs_coroutine.start(function()
                local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(vo.openType)
                local t = checkTable(CfUtils.Split(vo.openParameter))
                GoodsConfMgr:GetInstance():ExecuteJump(row, nil, nil, nil, t)
            end)
        end
    else
        if not self._cb then
            return
        end
        self._cb()
    end
end

function UIActivityPtTaskCellNode:PlanyAniByName(name)
end

function UIActivityPtTaskCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActivityPtTaskCellNode
